    if(noWinnerScoreCache)return noWinnerScoreCache;
    if(!noWinnerScorePromise)noWinnerScorePromise=fetch('/api/no-winner-score-profile'+(force?'?refresh='+Date.now():''),{cache:'no-store'}).then(async r=>{const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||('HTTP '+r.status));noWinnerScoreCache=d;return d;}).finally(()=>{noWinnerScorePromise=null;});
    return noWinnerScorePromise;
