  function renderDecisionNumberMode(){const labels={choose:'Modo Escolher: clique para adicionar ou remover. Dois cliques fixam; três excluem.',fix:'Modo Fixar: clique uma vez para fixar. Clique de novo em uma fixa para desafixar.',exclude:'Modo Excluir: clique uma vez para excluir. Clique de novo em uma excluída para liberar.',release:'Modo Liberar: clique em uma fixa ou excluída para liberar.'};$$('[data-decision-number-action]').forEach(b=>{const active=b.dataset.decisionNumberAction===state.decisionBallMode;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});const status=$('#decision-number-mode-status');if(status)status.textContent=labels[state.decisionBallMode]||labels.choose;}
