  function saveGames(games){
    const normalized=(games||[]).map(g=>M.normalize(g)).filter(Boolean);
    if(!normalized.length)return toast('Nenhum jogo válido para salvar.');
    let added=0;
    for(const g of normalized){
      const sorted=[...g].sort((a,b)=>a-b);
      if(!state.savedGames.some(x=>keyOf(x.game)===keyOf(sorted))){
        const now=new Date().toISOString();
        state.savedGames.push({id:`${Date.now()}-${Math.random().toString(36).slice(2)}`,savedAt:now,updatedAt:now,game:sorted,note:'',classification:'principal'});
        added++;
      }
    }
    savePrefs();
    renderMyGames();
    renderSavedGames();
    if(added)queueCloudSync();
    toast(added?`${added} jogo(s) salvo(s).`:'Este jogo já estava salvo.');
  }

