    const fmt=a=>(a||[]).map(n=>pad(Number(n))).join(' · ');
    const statHTML=(rows,label)=>`<div class="summary-row"><span>${label}</span><b>${(rows||[]).slice(0,12).map(x=>`${pad(x.n)} <small>top ${x.appearances}/${d.topCount} · melhor #${x.bestRank||'—'}</small>`).join(' · ')||'—'}</b></div>`;
    el.className='analytics-card';
    el.innerHTML=`<div class="panel-head"><div><span class="eyebrow dark">MÉTODO CORRIGIDO · ${d.pattern}</span><h3>Composição fixa · dezenas abertas à disputa por score</h3><p class="muted">A composição define somente ${d.part1Count} vagas na Parte 1, ${d.mid?'13 obrigatória':'sem 13'} e ${d.part2Count} vagas na Parte 2. Nenhuma dezena é pré-fixada por QG/FG ou ordem manual.</p></div><span class="status-pill ok">SCORE M51</span></div><div class="stats-kpis bi-kpis"><article><span>Combinações avaliadas</span><b>${Number(d.tested||0).toLocaleString('pt-BR')}</b><small>universo exato da composição</small></article><article><span>Aprovadas nos filtros</span><b>${Number(d.approvedCount||0).toLocaleString('pt-BR')}</b><small>Matriz 51 + estruturas obrigatórias</small></article><article><span>Score vencedor</span><b>${Number(d.score||0).toFixed(2).replace('.',',')}</b><small>rank ${Number(d.rankScore||0).toFixed(2).replace('.',',')}</small></article><article><span>Top analisado</span><b>${d.topCount}</b><small>para contribuição por dezena</small></article></div><div class="summary-stack"><div class="summary-row"><span>Jogo vencedor</span><b>${fmt(d.game)}</b></div>${statHTML(d.part1Stats,'Parte 1 · presença entre os melhores jogos')}${statHTML(d.part2Stats,'Parte 2 · presença entre os melhores jogos')}<div class="summary-row"><span>Regra aplicada</span><b>estrutura primeiro; escolha das dezenas decidida pelo score do jogo completo</b></div><div class="summary-row"><span>Futuro usado</span><b>NÃO · somente histórico carregado antes da próxima indicação</b></div></div>`;
