  function verticalRatioLabel(hits,total){return `${hits?hits:'-'}/${total?total:'-'}`;}
  function verticalPatternModes(history,windowSize){
    const labels=verticalBandLabels();
    const modes=new Map(labels.map(label=>[label,{patterns:new Map(),eligible:0}]));
    // A média do painel não inclui o concurso atualizado; o padrão segue a mesma amostra.
    const end=history.length-1,start=Math.max(windowSize,end-windowSize);
    for(let i=start;i<end;i++){
      const previous=new Set(history[i-1].dezenas),current=new Set(history[i].dezenas);
      const freq=Object.fromEntries(ALL.map(n=>[n,0]));
      history.slice(i-windowSize,i).forEach(d=>d.dezenas.forEach(n=>freq[n]++));
      const bands=new Map(labels.map(label=>[label,{total:0,hits:0}]));
      for(const n of ALL){const label=verticalPctBand(freq[n]/windowSize*100).label,band=bands.get(label);band.total++;if(previous.has(n)&&current.has(n))band.hits++;}
      for(const [label,band] of bands){if(!band.total)continue;const entry=modes.get(label),key=`${band.hits}/${band.total}`;entry.eligible++;entry.patterns.set(key,(entry.patterns.get(key)||0)+1);}
    }
    return modes;
  }
